10|    let fallbackImage: NSImage?
11|    @State private var image: NSImage?
12|    @State private var isLoading = false
13|
14|    init(filename: String, cacheURL: ValidatedPreviewCacheURL?, fallbackImage: NSImage?) {
15|        self.filename = filename
16|        self.cacheURL = cacheURL
17|        self.fallbackImage = fallbackImage
18|        _image = State(initialValue: fallbackImage)
19|    }
20|
21|    var body: some View {
22|        Group {
23|            if let image {
24|                GeometryReader { proxy in
25|                    Image(nsImage: image)
26|                        .resizable()
27|                        .scaledToFit()
28|                        .frame(width: proxy.size.width, height: proxy.size.height)
29|                }
30|                .accessibilityLabel(filename)
