45|            image = nil
46|            let worker = Task.detached(priority: .userInitiated) {
47|                cacheURL.readData().flatMap(NSImage.init(data:)).map(SendableImage.init)
48|            }
49|            let prepared = await withTaskCancellationHandler {
50|                await worker.value
51|            } onCancel: {
