110|private struct PDFKitCanvas: NSViewRepresentable {
111|    let document: PDFDocument?
112|
113|    func makeNSView(context: Context) -> PDFView {
114|        let view = PDFView()
115|        view.autoScales = true
116|        view.document = document
117|        updateAccessibility(in: view)
118|        DispatchQueue.main.async { updateAccessibility(in: view) }
119|        return view
120|    }
121|
122|    func updateNSView(_ nsView: PDFView, context: Context) {
123|        if nsView.document !== document { nsView.document = document }
124|        updateAccessibility(in: nsView)
125|        DispatchQueue.main.async { updateAccessibility(in: nsView) }
126|    }
127|
128|    private func updateAccessibility(in view: NSView) {
129|        let pageCount = document?.pageCount ?? 0
130|        view.setAccessibilityLabel("PDFKit 安全缓存预览，\(pageCount) 页")
131|        labelPDFHierarchy(in: view, pageCount: pageCount)
132|        labelPDFVirtualElements(view.accessibilityChildren() ?? [], pageCount: pageCount)
133|    }
134|
135|    private func labelPDFHierarchy(in view: NSView, pageCount: Int) {
136|        let role: NSAccessibility.Role? = view.accessibilityRole()
137|        let label: String? = view.accessibilityLabel()
138|        if role == .group, label?.isEmpty != false {
139|            view.setAccessibilityLabel("PDF 文档页面内容，共 \(pageCount) 页")
140|            view.setAccessibilityIdentifier("PDF 文档页面内容")
141|        }
142|        for subview in view.subviews {
143|            labelPDFHierarchy(in: subview, pageCount: pageCount)
144|        }
145|    }
146|
147|    private func labelPDFVirtualElements(_ elements: [Any], pageCount: Int) {
148|        for element in elements {
149|            guard let virtualElement = element as? NSObject,
150|                  virtualElement.responds(to: NSSelectorFromString("accessibilityLabel")) else { continue }
151|            let role = virtualElement.value(forKey: "accessibilityRole") as? String
152|            let label = virtualElement.value(forKey: "accessibilityLabel") as? String
153|            if label?.isEmpty != false, let fallback = fallbackLabel(forRole: role, pageCount: pageCount) {
154|                virtualElement.setValue(fallback, forKey: "accessibilityLabel")
155|            }
156|            let children = virtualElement.value(forKey: "accessibilityChildren") as? [Any] ?? []
157|            labelPDFVirtualElements(children, pageCount: pageCount)
158|        }
159|    }
160|
161|    private func fallbackLabel(forRole role: String?, pageCount: Int) -> String? {
162|        switch role {
163|        case NSAccessibility.Role.group.rawValue:
164|            return "PDF 页面容器，共 \(pageCount) 页"
165|        case NSAccessibility.Role.button.rawValue:
166|            return "PDF 滚动控制"
167|        case "AXIncrementArrow":
168|            return "向前滚动 PDF"
169|        case "AXDecrementArrow":
170|            return "向后滚动 PDF"
171|        default:
172|            return nil
173|        }
174|    }
